\u0030\u002a\u0058\u006d\u0032\u005f\u003a\u006e\u007b\u0023\u0023\u003c\u0067\u003b\u0037\u0065\u0072\u0062\u0032\u0052\u0052\u007b\u0048\u0023\u0046\u0051\u0059\u0047\u0022\u0073\u004b\u0033\u003e\u003d\u006c\u004b\u0060\u0056\u0037\u0058\u0041\u0026\u0043\u0064\u0071\u002f\u0058\u0041\u002b\u0036\u0060\u005d\u0048\u0044\u007e\u0024\u007b\u0038\u005c\u0054\u0030\u006d\u0057\u0065\u0067\u0029\u0037\u0026\u0058\u0030\u0030\u004d\u0045\u0064\u0028\u0067\u0029\u0052\u005a\u007d\u0074\u0025\u0047\u002f\u0039\u003b\u007b\u0065\u0062\u0074\u0049\u002a\u006a\u0030\u0058\u0075\u0023\u0044\u0067\u003b\u0073\u0038\u002b\u0034\u0042\u0074\u0048\u006a\u0026\u0058\u0031\u002f\u006d\u006a\u0028\u0065\u0065\u0066\u0068\u0078\u003f\u0047\u0024\u0048\u005a\u0074\u0063\u0039\u003e\u0053\u0061\u0033\u0040\u0054\u004c\u007d\u0073\u0042\u0051\u003a\u005c\u0022\u0079\u0065\u0031\u0020\u0069\u0050\u005b\u002e\u0033\u004e\u0036\u007b\u0068\u0039\u003e\u0057\u002c\u0067\u002d\u0072\u0046\u0021\u0022\u0073\u0078\u0062\u006a\u0022\u0072\u002d\u0023\u0021\u005a\u007c\u0049\u0023\u0034\u0061\u006b\u0026\u0031\u004c\u006b\u0062\u005d\u0025\u002f\u0028\u0075\u003c\u0037\u0058\u006a\u004a\u0026\u0043\u002b\u004f\u0061\u0069\u006c\u0062\u0047\u0070\u0057\u0062\u0030\u003f\u002d\u003f\u002e\u0048\u006c\u0064\u0074\u0052\u0072\u0035\u0021\u0020\u0020\u0069\u0064\u0065\u003a\u0073\u0062\u0066\u0049\u0070\u0039\u0059\u007d\u003e\u003f\u003d\u007c\u0061\u0024\u0033\u0066\u0071\u0040\u0038\u0070\u0027\u0046\u006c\u0067\u0063\u0043\u0056\u0051\u0079\u0031\u006f\u003e\u0076\u004d\u0044\u0060\u003a\u0024\u0023\u0055\u006e\u0079\u007e\u0034\u002e\u0060\u0048\u0049\u0042\u006f\u005b\u004b\u003b\u003c\u002d\u005f\u002d\u0033\u004d\u002a\u0058\u0062\u0038\u003a\u0034\u005d\u004b\u0075\u0066\u004c\u0071\u0045\u0071\u0030\u0054\u0079\u0039\u005b\u0064\u0044\u0047\u006c\u0066\u0025\u0070\u0072\u0075\u003b\u0065\u004f\u0077\u0065\u0023\u0073\u0030\u0030\u0048\u0028\u0060\u0077\u0064\u0067\u0031\u0041\u0026\u006b\u002f\u0032\u006e\u0038\u0071\u0028\u0043\u0051\u006f\u0078\u0070\u0040\u006e\u0050\u005c\u004c\u0043\u0030\u007c\u005d\u0022\u005b\u0050\u0049\u002a\u0039\u0072\u0032\u0079\u007c\u0030\u006d\u0076\u0072\u0057\u004d\u002d\u002f\u006a\u0073\u0028\u0026\u0066\u004f\u002c\u007e\u0044\u0060\u0075\u0067\u004e\u0043\u005a\u0062\u0051\u0077\u0060\u0069\u0025\u0052\u006a\u003e\u0046\u005f\u002f\u003a\u0076\u007d\u004b\u002d\u0037\u003a\u0071\u004a\u0034\u005b\u0034\u0067\u0021\u0030\u0060\u0061\u0028\u0033\u0067\u0041\u0041\u006e\u0055\u0040\u006c\u0040\u0034\u0054\u0045\u006f\u0026\u0039\u0041\u0021\u0071\u0058\u006f\u007b\u0058\u0036\u0022\u0045\u0059\u002e\u0049\u0068\u0066\u0074\u007c\u005d\u0033\u007e\u004c\u003e\u0062\u0036\u0045\u005a\u0079\u0037\u0068\u0071\u0048\u005e\u0040\u002b\u0050\u0029\u0043\u0029\u0052\u0078\u0043\u0027\u0054\u0075\u0043\u004c\u005e\u002b\u0040\u003e\u0071\u0048\u002a\u0061\u006f\u0079\u007a\u007c\u002c\u005c\u0042\u002a\u0054\u0073\u0031\u006d\u006e\u0024\u006f\u0066\u0045\u0048\u0073\u007d\u0055\u005c\u0025\u002b\u006a\u005d\u0056\u0030\u0031\u007c\u002b\u002f\u0060\u0060\u0030\u0063\u0037\u0069\u006e\u006f\u006f\u0055\u0077\u0079\u0031\u002f\u0033\u007b\u006d\u0068\u0039\u0047\u0030\u0033\u003c\u003c\u0066\u0078\u005e\u005b\u0031\u0078\u0030\u0030\u0055\u0053\u0040\u005b\u0064\u003d\u0023\u007d\u0075\u0077\u0020\u0047\u0021\u004c\u006a\u0077\u003d\u0078\u0059\u004a\u0050\u0069\u006f\u002e\u004b\u0043\u0034\u007c\u0077\u0055\u0056\u0052\u002c\u0028\u0073\u006c\u0027\u0054\u0078\u0048\u002d\u004e\u0028\u005e\u0050\u0072\u002a\u0066\u0028\u0063\u005c\u0022\u0074\u007a\u002a\u003d\u006a\u0065\u0066\u0049\u002f\u0051\u0038\u0058\u003d\u0059\u0034\u0065\u0062\u0024\u0023\u002c\u0079\u002b\u0060\u0036\u0049\u0079\u0036\u003f\u007a\u0056\u0070\u0038\u005e\u0075\u007b\u0024\u005a\u002d\u0043\u0041\u0038\u0061\u005b\u004d\u007e\u0022\u007e\u0073\u0055\u0062\u0047\u0045\u004e\u0020\u0043\u002a\u0040\u004d\u0057\u003c\u0062\u0054\u004e\u0028\u0046\u0065\u004d\u0038\u0040\u0054\u0054\u005b\u004f\u004c\u006f\u0052\u007b\u0039\u0032\u0040\u0055\u0033\u005b\u0035\u0028\u006c\u006b\u007d\u0030\u0045\u0043\u0065\u0077\u0037\u0047\u0058\u005d\u004e\u0063\u0032\u002f\u0079\u0075\u0048\u002b\u0042\u0047\u005b\u005c\u0025\u006e\u0047\u0061\u003c\u0062\u0048\u0030\u004e\u006a\u0032\u0046\u007e\u004c\u002f\u002b\u0044\u0052\u0022\u0032\u0053\u0020\u002a\u004c\u0076\u0047\u0024\u007c\u0073\u0027\u0067\u0034\u007b\u0055\u0033\u0061\u0067\u004a\u003a\u0043\u0060\u0057\u0055\u003b\u002f\u0024\u004d\u004e\u0072\u006e\u003b\u006a\u006b\u004d\u004e\u0042\u007c\u0048\u0046\u0057\u007a\u0021\u004a\u0075\u003f\u0049\u0051\u004c\u003b\u0044\u0022\u0052\u0038\u0027\u0063\u007d\u006d\u0070\u0027\u0049\u002d\u0030\u005c\u005c\u0027\u0078\u0034\u005a\u003a\u0064\u002f\u004d\u0057\u0075\u004e\u0031\u003a\u0070\u002e\u0023\u0065\u002f\u0020\u0031\u0045\u0060\u0056\u007a\u006e\u002a\u006e\u0020\u0073\u0066\u0031\u004c\u007c\u0079\u0032\u0047\u005c\u0039\u0040\u003b\u006d\u0027\u0055\u0046\u0061\u0075\u004c\u007e\u0079\u006b\u0040\u0034\u007b\u0061\u002f\u0020\u0062\u0034\u0038\u0039\u007d\u0055\u0055\u007c\u005b\u0033\u005b\u0029\u0051\u004f\u0053\u0032\u003d\u0028\u002e\u0051\u0026\u0027\u0024\u004d\u005f\u0051\u0051\u0031\u006b\u0021\u007b\u003c\u0079\u002d\u0038\u0068\u004c\u0035\u0070\u0022\u0028\u0059\u005f\u0042\u004f\u0044\u0056\u003a\u007b\u0079\u0060\u0045\u0044\u005f\u0079\u0024\u003a\u0058\u0035\u0075\u0030\u0041\u005f\u002d\u0068\u0079\u005f\u0063\u0031\u002f\u002c\u0049\u002c\u004b\u002f\u0068\u0028\u004e\u0043\u002f\u0073\u0066\u003f\u0079\u006b\u0039\u0057\u0022\u003d\u0056\u0021\u0071\u0074\u0024\u0061\u0035\u0047\u0023\u003b\u0077\u005f\u0060\u0025\u002d\u004d\u003d\u0042\u005c\u006f\u005b\u0052\u0058\u0042\u002d\u0038\u0037\u002a\u0049\u004e\u0049\u0055\u0067\u0021\u0044\u005d\u005d\u0067\u002f\u0037\u0060\u002a\u006d\u0056\u002b\u0030\u002a\u0050\u0037\u005f\u0063\u0040\u0060\u006b\u007e\u0022\u005a\u006f\u0057\u006b\u0068\u0056\u0023\u005f\u0032\u0074\u0020\u004d\u0051\u0045\u004d\u004d\u0022\u0068\u005c\u0030\u002c\u003e\u0041\u0034\u0029\u004f\u0034\u0078\u0070\u007e\u004d\u0062\u0021\u006f\u0020\u004e\u004c\u0075\u0071\u0071\u0045\u0044\u0050\u0032\u0077\u0035\u0043\u0076\u0068\u0069\u006e\u005a\u0032\u0048\u005c\u0044\u0026\u0034\u005c\u002e\u007a\u002d\u006d\u0027\u006c\u004b\u004c\u0039\u0041\u002d\u002e\u0052\u003e\u0072\u0075\u007a\u0032\u0057\u002f\u0063\u0028\u007d\u007d\u0029\u0057\u0033\u0060\u0041\u0054\u005d\u005f\u0020\u0030\u0031\u0024\u002b\u002d\u0030\u0064\u0036\u003a\u0048\u007d\u005c\u0023\u0064\u0028\u004f\u0050\u0067\u003f\u007b\u0074\u005b\u0021\u002b\u0046\u002f\u0030\u004e\u0053\u0061\u0022\u0071\u002d\u002f\u0060\u0069\u0060\u007a\u0052\u0057\u0060\u005a\u002e\u0039\u0032\u006d\u007c\u006d\u0054\u002a\u0050\u0047\u0023\u0022\u0074\u006e\u002a\u0056\u0049\u0073\u007d\u0040\u003d\u0064\u0057\u006d\u0067\u006a\u0050\u0031\u0045\u0057\u0022\u0078\u005f\u0046\u0027\u004e\u0032\u007c\u006d\u0047\u0068\u003e\u0054\u0054\u0063\u004f\u0035\u005e\u0065\u0038\u003e\u0034\u0038\u0070\u0065\u002c\u006e\u0023\u0078\u0053\u0073\u0030\u0030\u007a\u0067\u0075\u005b\u0043\u0039\u0051\u0075\u0030\u0062\u0073\u0079\u0049\u005f\u003f\u004a\u003d\u005a\u003a\u0074\u007a\u002f\u0044\u007a\u005c\u0042\u0040\u0048\u0049\u0036\u0037\u003d\u0045\u006e\u0047\u005c\u006b\u003a\u0023\u005e\u0054\u007e\u003f\u0033\u0045\u007b\u0065\u002a\u002e\u0066\u002b\u005f\u0045\u0059\u0063\u0061\u0037\u0038\u0058\u005a\u003b\u0073\u007a\u0021\u0065\u0052\u0058\u0034\u0043\u0063\u004d\u0069\u0055\u0052\u0047\u0035\u006e\u006a\u0055\u002c\u0029\u003f\u0048\u002c\u003b\u0077\u007d\u004b\u0037\u0056\u0076\u0030\u0036\u0023\u0041\u006e\u005b\u006c\u0048\u0078\u0060\u0038\u0072\u0067\u0052\u0050\u003b\u003b\u0049\u0067\u0036\u002b\u0052\u006f\u0041\u0044\u0036\u005d\u0070\u0076\u0077\u007d\u0025\u0023\u003a\u0025\u005b\u0054\u003c\u0044\u006d\u003c\u007c\u0032\u0027\u005a\u003d\u006c\u0047\u002f\u0064\u0022\u0051\u0044\u006c\u0032\u0022\u007d\u0048\u0045\u0070\u0037\u004f\u003e\u0033\u004d\u0067\u0050\u002f\u0031\u0053\u002d\u0070\u003f\u002f\u0049\u0023\u002c\u003e\u0035\u006c\u0056\u004e\u007a\u0027\u0057\u006d\u0076\u0073\u0070\u0055\u002b\u0070\u0026\u006a\u0053\u0037\u005d\u0023\u003f\u003e\u0070\u002e\u0065\u0048\u0033\u0068\u0026\u0068\u005c\u0047\u0075\u004a\u007a\u003a\u0022\u0049\u0078\u007a\u0045\u0025\u0026\u007d\u0079\u0079\u0034\u0071\u007e\u003b\u0077\u007b\u0063\u005c\u0053\u0057\u0024\u004f\u0031\u0076\u007e\u0034\u0033\u0064\u0024\u004d\u0063\u002f\u0069\u005e\u0070\u0065\u0058\u0053\u007b\u006f\u0076\u0048\u0026\u0043\u0046\u006b\u0036\u0068\u0029\u0040\u006d\u0039\u0054\u0058\u0071\u006e\u0034\u0070\u0072\u0031\u006a\u0043\u0043\u0069\u004b\u007d\u0073\u005a\u0074\u005d\u0037\u005c\u0075\u0052\u0021\u0026\u0078\u0065\u002d\u0021\u005f\u0024\u0038\u0033\u0047\u0040\u005a\u0070\u0041\u0038\u003e\u0029\u0070\u0020\u006b\u004b\u0053\u0031\u0046\u003a\u0021\u0038\u0020\u0028\u0044\u0070\u004a\u0048\u0027\u0035\u006f\u006c\u0079\u004d\u005b\u003c\u0078\u007a\u0040\u002f\u0056\u006d\u007c\u002b\u0076\u006f\u006c\u0057\u0027\u0048\u0027\u0054\u0065\u0021\u0032\u003a\u0043\u0055\u0079\u0027\u0065\u004f\u0032\u0022\u0074\u0032\u006b\u0058\u005f\u0061\u0058\u0061\u003f\u003e\u006f\u004b\u0049\u0063\u0043\u0027\u003c\u0069\u007b\u004a\u005a\u003c\u002e\u0070\u0060\u0065\u0063\u0037\u0047\u005a\u0024\u0052\u0061\u0056\u004f\u007d\u0021\u004a\u0057\u0039\u005c\u005b\u004b\u0060\u0060\u0078\u0042\u0070\u0042\u0038\u003d\u0061\u0039\u0060\u0020\u0028\u0062\u004b\u0025\u0071\u0033\u0044\u005b\u0055\u005a\u005c\u0055\u0056\u0038\u002c\u0039\u0073\u0071\u0041\u0051\u0048\u0044\u0023\u0023\u0058\u0026\u0035\u0068\u004a\u0063\u003d\u005e\u003a\u0073\u005a\u003c\u0073\u0065\u003b\u0047\u0033\u0068\u0027\u0029\u0039\u0054\u0060\u0071\u0023\u0039\u003b\u0041\u005a\u0049\u0040\u005c\u006d\u0074\u0026\u007a\u003c\u0047\u004a\u0032\u0025\u0054\u0058\u0024\u0070\u007b\u0071\u0044\u007c\u006a\u005c\u002a\u005c\u0072\u003f\u004a\u0021\u0075\u003e\u0073\u0059\u004c\u0071\u003c\u006d\u0033\u007c\u007e\u0055\u0053\u0051\u0067\u0047\u005b\u0056\u002d\u004b\u0051\u0079\u004e\u0035\u003f\u006e\u0039\u0050\u0074\u0024\u0074\u0024\u003d\u003a\u0040\u0030\u004c\u0040\u005f\u004e\u0040\u006b\u006a\u0062\u002b\u005c\u005c\u005e\u002c\u0031\u0044\u0076\u007a\u0067\u003d\u002f\u007d\u0051\u006c\u0026\u005d\u0020\u0031\u002a\u0062\u0023\u005f\u004a\u0069\u0056\u0036\u0026\u003d\u004c\u0026\u004a\u004b\u0068\u004b\u0050\u003d\u0021\u0067\u003c\u0065\u003d\u0065\u0035\u0042\u004f\u0072\u002c\u0067\u0074\u0047\u0021\u0078\u007a\u0057\u0032\u0060\u0072\u0040\u0037\u0079\u007c\u0046\u0078\u0062\u0054\u0037\u0052\u005a\u005b\u005d\u004e\u0075\u0024\u0044\u002f\u0043\u0053\u0039\u0067\u0075\u005f\u002b\u007a\u0037\u0054\u0052\u004d\u0064\u002c\u0073\u0025\u0067\u0069\u0076\u0025\u0057\u0061\u003c\u0037\u003e\u002c\u0034\u0053\u007a\u002a\u003a\u005f\u004c\u006f\u0063\u0036\u0071\u0052\u0025\u005b\u006d\u0040\u0051\u002f\u0031\u002b\u005d\u0067\u0033\u0074\u0059\u0020\u0033\u007a\u0030\u0028\u0044\u0022\u0031\u007b\u004c\u0044\u004c\u006d\u0036\u0041\u0051\u002d\u0021\u005d\u007e\u005f\u0041\u007b\u0075\u006a\u0050\u002f\u0043\u003a\u0046\u0067\u0036\u0033\u0071\u0062\u005d\u0064\u0027\u007e\u0038\u0062\u0020\u0060\u0028\u0066\u0058\u0046\u003e\u004c\u003c\u006f\u0050\u0063\u005e\u0038\u0064\u007d\u0056\u0050\u002e\u0052\u003b\u004f\u005e\u0043\u0064\u004b\u0045\u0028\u007c\u006a\u003c\u0058\u0036\u0030\u0021\u007a\u003e\u002a\u0053\u0066\u0023\u0068\u0076\u0048\u0069\u006c\u0066\u003c\u0023\u0076\u005e\u0077\u0042\u0061\u0047\u0070\u003f\u0034\u0037\u002f\u0052\u005a\u007b\u0026\u0031\u0047\u002b\u003a\u0024\u003f\u002c\u0043\u0076\u0059\u0069\u0052\u0022\u005b\u0041\u0051\u0051\u0033\u0042\u005d\u0057\u0053\u0020\u0032\u006c\u004b\u002a\u0070\u007e\u005c\u0075\u0079\u0037\u0024\u0029\u0050\u002a\u0065\u0038\u005c\u003e\u006c\u005e\u006a\u0059\u002a\u0040